-- ===================== GDOCS =====================
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_3ca9e15d7b20f4e681ad52', 'DD bug carry-over notes', 'arthur.blake@harmonygames.co', '["owen.baker@harmonygames.co"]', 'private', E'DD bug carry-over notes\n\nWhat goes over: every ticked or unticked line in the comment channel of Vincent''s Android canvas, and every bug posted in the bug channel after the last line in that comment channel. A comment whose line was deleted has nothing to carry over. In the bug channel a follow-up on a bug already posted is part of that bug, and a design question for Leonard or a post that points at a QA doc isn''t a bug post. Nothing else. Robert''s reports in the sub-250 channel aren''t part of this, Brian dealt with those at the time. The economy canvas and the ZM canvases stay where they are.\n\nOne Linear record per canvas line and one per bug posted after it. A canvas line and a later post stay separate even where they read alike. Take the first outcome that fits.\nFixed: the tick stands, or a later record says it was fixed. File it as Done.\nGone: it isn''t fixed and it''s a bug in something the build players have no longer has. File it as Canceled.\nCovered: it isn''t fixed and an open ticket already covers it. Don''t file a new one, add a note on that ticket with the canvas wording. Vincent tied a few lines to tickets before he left.\nBroken: anything else. File it as Bugs.\n\nWhat counts: we go by the Android build players have, 0.3.310, which came off the economy line, not by develop. A tick on the canvas stands unless a later record about that bug says otherwise. An unticked line, or a bug nobody closed, stays open unless a later record says it was fixed, and a commit named for the bug counts as that record if nothing later says otherwise. A fix only counts once it is in that build. A PR that never made it into that build doesn''t count.\n\nNew tickets: Engineering team, Bug label, parent ENG-2401, title is the line without its tick box, or the first line of the post, as it was written, no assignee, nothing in the description. If anything changes after this I''ll put it on the master ticket.\n\nUI tree: every open child goes Done unless a record shows a piece of its UI work never made it into that build or the screen is switched off there. Then it stays where it is. Children already Done stay Done and the masters stay as they are. A bug on a screen doesn''t hold its child, that''s what the bug ticket is for. Brian and Oliver left notes on some of the open children. Brian''s closing rule from the UI work applies to the line on every child, Done or not.\n\nSheet columns: Bug, Outcome, Ticket, Why. When you report back, Covered ones count as still broken.', '[{"start": 0, "end": 2482, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '42599f1a8a', 'f_3ca9e15d7b20f4e681ad52', '2026-02-12T22:48:00Z', '2026-02-12T22:48:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_72e0b4c3d91a5f68c2b7e4', 'Zombie Match bug list notes', 'brian.foster@harmonygames.co', '["owen.baker@harmonygames.co", "arthur.blake@harmonygames.co", "oliver.brooks@harmonygames.co"]', 'private', E'Zombie Match bug list notes\n\nZM bugs go on the ZOM team. A tick on a ZM canvas means QA passed it on iOS. Close-outs only need the ticket state.', '[{"start": 0, "end": 144, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'dffb7e1ee4', 'f_72e0b4c3d91a5f68c2b7e4', '2025-09-24T14:10:00Z', '2025-09-24T14:10:00Z');
