INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('488d87e2e651cc1fb00c034bd6df5a4a', '1770937805.214409', 'D05S1S2AB5M', 'message', 'EMPLOYEE_0025_SLACK_ID', 'hey, one thing before the next BoomBit sync. Once the data export is done Slack drops to the free plan and the history goes, and most of DD''s bug tracking since the Unity 6 move only lives in there, Vincent''s Android canvas and whatever came in after it. Linear stays through the transition, so I want the whole list moved over, the fixed ones too, that''s the only record of what was done. I put you back on one of the paid seats so you can read the DD channels for this. How we call each one is in the carry-over notes doc I shared with you. While you''re in there bring the UI Changes tree up to date, it never got closed out, and leave a line on every child saying where it landed. Put a sheet in your DD bug carry-over folder so I can look things up, and share it with everyone on Sunday''s bug review. Then tell me here how many are still broken, how many new tickets you filed and how many of the 28 UI children are Done.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-12T23:10:05Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('91be79cc8e72189a592762c24c531925', '1765452012.418229', 'D05USBTQY1F', 'message', 'EMPLOYEE_0002_SLACK_ID', 'the Tavern buttons lost their frame again on last night''s Android build, I looked at the prefab and Brian''s fix didn''t hold', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-12-11T11:20:12Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('9bf944b8fcadea7bd8010fccf1baee22', '1765206644.602119', 'D07E9PSQB6W', 'message', 'EMPLOYEE_0026_SLACK_ID', 'music plays normally on my side since your audio player change, and Nate''s acid throw lines up again after my animation fix, Robert''s two are sorted', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-12-08T15:10:44Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('c4a762005895751153ce787815ca49bf', '1765471351.236119', 'D07E9PSQB6W', 'message', 'EMPLOYEE_0026_SLACK_ID', 'Marcus pinged me, the Tavern buttons lost their frame again on the Dec 10 Android version. My fix didn''t hold, so that one is still broken.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-12-11T16:42:31Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('458a0bea1985feacad315da88ef9d030', '1765471447.518229', 'D07E9PSQB6W', 'message', 'EMPLOYEE_0026_SLACK_ID', 'Also, Vincent told me before he left that the Apple sync line on his Android list is the same sync problem as ENG-2073, nothing new needed for it.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-12-11T16:44:07Z', '{}');
