VALUES ('2ea7c02c6ddb99bc9b37f680be4159a6', '1765471563.704419', 'D07E9PSQB6W', 'message', 'EMPLOYEE_0026_SLACK_ID', 'And I never got back to the two popups from Arthur''s reviews: the Axe Arena info popup still has the old frame and the Tile Dozer how-to-play popup still points at the old sprites.', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-12-11T16:46:03Z', '{}');
INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('e48eb03d633e480ea6f7cddea576ef4c', '1764606918.318209', 'C09Q4S613CN', 'message', 'EMPLOYEE_0026_SLACK_ID', 'I was back in the shop prefabs today, the round icons on the River Tile and Memory Tile shops are there again on the current build, so don''t trust that tick', '37dc1365297989005c98ca1012808d6e', '1764042435.541279', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2025-12-01T16:35:18Z', '{}');
